.movie-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 10px;
}

.movie-item {
  text-align: center;
}

.movie-item img {
  width: 100%;
  height: auto;
  border-radius: 4px;
}

sp_widget.script:
(function() {
    data.movies = [];
    var gr = new GlideRecord('x_1080820_mvx_movie');

    if (options.type == "top_rated") {
        gr.orderByDesc('tmdb_rating');
        data.title = "Top Rated";
    } else if (options.type == "newest") {
        gr.orderByDesc('release_date');
        data.title = "Newest";
    }
    gr.query();

    while (gr.next() && data.movies.length < 8) {
        data.movies.push({
            title: gr.title.toString(),
            poster: gr.poster_url.toString(),
            release: gr.release_date.toString(),

			titleK: gr.getValue('title'),
            poster_urlK: gr.getValue('poster_url'),

			url: '?id=movie_detail&sys_id=' + gr.getValue('sys_id')
        });
    }
	data.q = $sp.getParameter('q'); // search text zo search page

	return data.movies;
})();
